# R reference values for gaply_core::stats_dist's chi-square upper tail and
# Fisher's exact test for a 2 x 2 table (Research OS, Phase 8X-1, decision
# 576), the distributions of stats.analyze.crosstabs.
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_xtab_dist_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only (stats). make_dist_fixtures.R is a separate script and is
# not run by this one, so its four files are untouched. Writes, next to this
# script, two files, each with a '#' header naming this script, R's version
# and the call, then a CSV body with every number as %.17g:
#
#   chi_p.csv     df,x,p                         p = pchisq(x, df, lower.tail = FALSE)
#   fisher_p.csv  a,b,c,d,two_sided,less,greater fisher.test(matrix(c(a, c, b, d), 2))
#
# The 2 x 2 table is [a b; c d]: a is row 1 and column 1, so in R's terms
# x = a, m = a + c (the first column's total), n = b + d and k = a + b (the
# first row's total). An x placed at a target p is placed through qchisq, and
# R's p is then computed from that x, so the row holds R's p of the exact
# double Gaply is given, not the target.
#
# Synthetic grids only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) sprintf("%.17g", as.numeric(x))

emit <- function(name, what, call, frame) {
  path <- file.path(here, name)
  writeLines(c(
    sprintf("# R's %s, for gaply_core::stats_dist (Research OS, Phase 8X-1).", what),
    "# Generated by /usr/local/bin/Rscript make_xtab_dist_fixtures.R (do not edit by hand).",
    sprintf("# %s, %s; %s.", R.version.string, R.version$arch, call)), path)
  write.table(frame, path, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)
  cat(sprintf("%s: %d rows\n", name, nrow(frame)))
}

# 1. The chi-square upper tail: 12 df up to 2,401 (a 50 x 50 table), each over
#    fixed x from 1e-14 above 0, x relative to the df, and x placed at target
#    p down to 1e-300, far above the df.
chi_df <- c(1, 2, 3, 4, 9, 25, 49, 100, 400, 1000, 2000, 2401)
x_fixed <- c(1e-14, 1e-10, 1e-6, 1e-3, 0.1, 0.5, 1, 2, 5)
x_rel <- c(0.25, 0.5, 0.9, 1, 1.1, 1.5, 2, 3)
p_target <- c(0.5, 0.05, 1e-3, 1e-6, 1e-12, 1e-20, 1e-50, 1e-100, 1e-200, 1e-300)
chi_rows <- list()
for (df in chi_df) {
  x_at <- sort(unique(c(x_fixed, x_rel * df, qchisq(p_target, df, lower.tail = FALSE))))
  chi_rows[[length(chi_rows) + 1]] <- data.frame(
    df = f17(df), x = f17(x_at), p = f17(pchisq(x_at, df, lower.tail = FALSE)))
}
emit("chi_p.csv", "upper tail of the chi-square", "pchisq(x, df, lower.tail = FALSE)",
     do.call(rbind, chi_rows))

# 2. Fisher's exact test: every table of cells 0 and 1; of cells 1, 3 and 5;
#    of cells 10, 25 and 50; unbalanced tables; tables with a zero margin;
#    and tables of a total of 100,000.
tables <- list()
add <- function(a, b, c, d) tables[[length(tables) + 1]] <<- c(a, b, c, d)
for (a in 0:1) for (b in 0:1) for (c in 0:1) for (d in 0:1) add(a, b, c, d)
for (a in c(1, 3, 5)) for (b in c(1, 3, 5)) for (c in c(1, 3, 5)) for (d in c(1, 3, 5)) add(a, b, c, d)
for (a in c(10, 25, 50)) for (b in c(10, 25, 50)) for (c in c(10, 25, 50)) for (d in c(10, 25, 50)) add(a, b, c, d)
add(1, 40, 30, 2); add(0, 50, 3, 1); add(100, 2, 5, 90); add(2, 98, 1, 0)
add(12, 5, 7, 300); add(500, 3, 2, 1); add(1000, 10, 10, 1000); add(7, 0, 0, 9)
add(0, 0, 3, 4); add(3, 0, 4, 0); add(0, 6, 0, 2); add(5, 2, 0, 0)
add(25000, 25000, 25000, 25000); add(25200, 24800, 24800, 25200)
add(25500, 24500, 24500, 25500); add(24900, 25100, 25100, 24900)
add(90000, 5000, 4000, 1000); add(99000, 500, 480, 20); add(50, 49950, 40, 49960)
fisher_rows <- list()
for (t in tables) {
  m <- matrix(c(t[1], t[3], t[2], t[4]), nrow = 2)
  p <- function(alt) fisher.test(m, alternative = alt)$p.value
  fisher_rows[[length(fisher_rows) + 1]] <- data.frame(
    a = f17(t[1]), b = f17(t[2]), c = f17(t[3]), d = f17(t[4]),
    two_sided = f17(p("two.sided")), less = f17(p("less")), greater = f17(p("greater")))
}
emit("fisher_p.csv", "Fisher's exact test for a 2 x 2 table",
     "fisher.test(matrix(c(a, c, b, d), 2), alternative = a)$p.value for two.sided, less and greater",
     do.call(rbind, fisher_rows))
